        meaning=by['house:119:2:312']['meaning'];require('permits implementation OR DECLINING implementation' in meaning and 'does not remove that framework or compel universal adoption' in meaning,'PURPAconsideration became universal adoption');require('100MEGAWATTS OR MORE at a SINGLE SITE OR CAMPUS' in meaning and 'legislature VOTED ON implementation' in meaning,'load threshold/prior-action exception differs');require(rows['house:119:2:313']['disposition']=='source_unresolved' and records['house:119:2:313']['exact_action_binding_unresolved'] and not records['house:119:2:313']['required_evidence_unavailable'] and 'cancelled independent source-version/glyph/table replay' in records['house:119:2:313']['rationale'],'WRDAretained restriction/source-availability boundary differs');require(read(data/'resume_receipt.json')['next_research_frontier']['later_delta_screened_count']==31,'later discovery frontier differs');require('house:119:2:313' in acc['material_source_gaps'],'source/version hold missing from accounting')
